CREATE DATABASE IF NOT EXISTS purugflow CHARACTER SET utf8mb4;
USE purugflow;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, senha VARCHAR(255) NOT NULL);
CREATE TABLE salas(id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, dono_id INT NOT NULL, FOREIGN KEY(dono_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE sala_membros(sala_id INT NOT NULL, user_id INT NOT NULL, PRIMARY KEY(sala_id,user_id), FOREIGN KEY(sala_id) REFERENCES salas(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE tarefas(id INT AUTO_INCREMENT PRIMARY KEY, sala_id INT NOT NULL, titulo VARCHAR(200) NOT NULL, descricao TEXT, estado ENUM('pendente','andamento','feita','cancelada') DEFAULT 'pendente', cor VARCHAR(9) DEFAULT '#111111', data DATE NOT NULL, responsavel_id INT NULL, FOREIGN KEY(sala_id) REFERENCES salas(id) ON DELETE CASCADE);
CREATE TABLE subtarefas(id INT AUTO_INCREMENT PRIMARY KEY, tarefa_id INT NOT NULL, titulo VARCHAR(200) NOT NULL, feita TINYINT(1) DEFAULT 0, FOREIGN KEY(tarefa_id) REFERENCES tarefas(id) ON DELETE CASCADE);
